<?php
namespace ChadPriddle\AppliedApi\Resources; use Illuminate\Http\Client\Response;
class ClientPolicies extends Resource { public function list($id,array $f=[]):Response{return $this->client->get('/policy/v1/clients/'.rawurlencode($id).'/policies',$this->q($f),[],true);} public function create($id,array $d):Response{return $this->client->post('/policy/v1/clients/'.rawurlencode($id).'/policies',$d);} public function addLine($id,array $d):Response{return $this->client->post('/policy/v1/policies/'.rawurlencode($id).'/lines',$d);} }